input.script:
# List all users first
users = list_users({})

# Define the dates for the week
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

# For each user and each date, get availability - this will be concurrent
availabilities = for user in users {
    user_avails = for date in dates {
        avail = get_availability({ user_id: user.id, date: date })
        return { user_id: user.id, date: date, busy: avail.busy }
    }
    return { user_id: user.id, name: user.name, days: user_avails }
}

return availabilities

users = boundary retry 3 {
    return list_users({})
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}

dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

availabilities = for user in users {
    user_avails = for date in dates {
        avail = boundary retry 2 {
            return get_availability({ user_id: user.id, date: date })
        } catch err {
            return fail("AVAIL_FAILED", err.code + ": " + err.message)
        }
        return { user_id: user.id, date: date, busy: avail.busy }
    }
    return { user_id: user.id, name: user.name, days: user_avails }
}

return availabilities
